from typing import List

def max_servings(n: int, q: List[int], a: List[int], b: List[int]) -> int:
    am = 10**6
    for i in range(n):
        if a[i] == 0:
            continue
        if am > q[i] // a[i]:
            am = q[i] // a[i]

    bm = 10**6
    for i in range(n):
        if b[i] == 0:
            continue
        if bm > q[i] // b[i]:
            bm = q[i] // b[i]

    ans = 0

    for servings_a in range(am + 1):
        remaining_ingredients = [q[i] - servings_a * a[i] for i in range(n)]
        servings_b = 10**6

        for i in range(n):
            if b[i] > 0:
                servings_b = min(servings_b, remaining_ingredients[i] // b[i])

        ans = max(ans, servings_a + servings_b)

    return ans
